9	#ifndef LLVM_LIBC_SRC_STRING_MEMORY_UTILS_UTILS_H
10	#define LLVM_LIBC_SRC_STRING_MEMORY_UTILS_UTILS_H
11	
12	#include "hdr/stdint_proxy.h" // intptr_t / uintptr_t / INT32_MAX / INT32_MIN
13	#include "src/__support/CPP/bit.h"
14	#include "src/__support/CPP/cstddef.h"
