22	#include <stddef.h> // size_t
23	
24	namespace LIBC_NAMESPACE_DECL {
25	
26	// Returns the number of bytes to substract from ptr to get to the previous
27	// multiple of alignment. If ptr is already aligned returns 0.
28	template <size_t alignment>
29	LIBC_INLINE uintptr_t distance_to_align_down(const void *ptr) {
30	  static_assert(cpp::has_single_bit(alignment),
31	                "alignment must be a power of 2");
32	  return reinterpret_cast<uintptr_t>(ptr) & (alignment - 1U);
33	}
34	
35	// Returns the number of bytes to add to ptr to get to the next multiple of
36	// alignment. If ptr is already aligned returns 0.
37	template <size_t alignment>
38	LIBC_INLINE uintptr_t distance_to_align_up(const void *ptr) {
39	  static_assert(cpp::has_single_bit(alignment),
40	                "alignment must be a power of 2");
41	  // The logic is not straightforward and involves unsigned modulo arithmetic
42	  // but the generated code is as fast as it can be.
43	  return -reinterpret_cast<uintptr_t>(ptr) & (alignment - 1U);
44	}
45	
46	// Returns the number of bytes to add to ptr to get to the next multiple of
47	// alignment. If ptr is already aligned returns alignment.
48	template <size_t alignment>
49	LIBC_INLINE uintptr_t distance_to_next_aligned(const void *ptr) {
50	  return alignment - distance_to_align_down<alignment>(ptr);
51	}
52	
53	// Returns the same pointer but notifies the compiler that it is aligned.
54	template <size_t alignment, typename T> LIBC_INLINE T *assume_aligned(T *ptr) {
55	  return reinterpret_cast<T *>(__builtin_assume_aligned(ptr, alignment));
56	}
57	
58	// Returns true iff memory regions [p1, p1 + size] and [p2, p2 + size] are
59	// disjoint.
60	LIBC_INLINE bool is_disjoint(const void *p1, const void *p2, size_t size) {
61	  const ptrdiff_t sdiff =
62	      static_cast<const char *>(p1) - static_cast<const char *>(p2);
63	  // We use bit_cast to make sure that we don't run into accidental integer
64	  // promotion. Notably the unary minus operator goes through integer promotion
65	  // at the expression level. We assume arithmetic to be two's complement (i.e.,
66	  // bit_cast has the same behavior as a regular signed to unsigned cast).
67	  static_assert(-1 == ~0, "not 2's complement");
68	  const size_t udiff = cpp::bit_cast<size_t>(sdiff);
69	  // Integer promition would be caught here.
70	  const size_t neg_udiff = cpp::bit_cast<size_t>(-sdiff);
71	  // This is expected to compile a conditional move.
72	  return sdiff >= 0 ? size <= udiff : size <= neg_udiff;
73	}
74	
75	#if __has_builtin(__builtin_memcpy_inline)
76	#define LLVM_LIBC_HAS_BUILTIN_MEMCPY_INLINE
77	#endif
78	
79	#if __has_builtin(__builtin_memset_inline)
80	#define LLVM_LIBC_HAS_BUILTIN_MEMSET_INLINE
81	#endif
82	
83	// Performs a constant count copy.
84	template <size_t Size>
85	LIBC_INLINE void memcpy_inline(void *__restrict dst,
86	                               const void *__restrict src) {
87	#ifdef LLVM_LIBC_HAS_BUILTIN_MEMCPY_INLINE
88	  __builtin_memcpy_inline(dst, src, Size);
89	#else
90	  // In memory functions `memcpy_inline` is instantiated several times with
91	  // different value of the Size parameter. This doesn't play well with GCC's
92	  // Value Range Analysis that wrongly detects out of bounds accesses. We
93	  // disable these warnings for the purpose of this function.
94	#ifndef LIBC_COMPILER_IS_MSVC
95	#pragma GCC diagnostic push
96	#pragma GCC diagnostic ignored "-Warray-bounds"
97	#if defined(LIBC_COMPILER_IS_GCC) && (LIBC_COMPILER_GCC_VER >= 1100)
98	#pragma GCC diagnostic ignored "-Wstringop-overread"
99	#endif // LIBC_COMPILER_IS_GCC && LIBC_COMPILER_GCC_VER >= 1100
100	#pragma GCC diagnostic ignored "-Wstringop-overflow"
101	#endif // !LIBC_COMPILER_IS_MSVC
102	  for (size_t i = 0; i < Size; ++i)
103	    static_cast<char *>(dst)[i] = static_cast<const char *>(src)[i];
104	#ifndef LIBC_COMPILER_IS_MSVC
105	#pragma GCC diagnostic pop
106	#endif // !LIBC_COMPILER_IS_MSVC
107	#endif
108	}
109	
110	using Ptr = cpp::byte *;        // Pointer to raw data.
111	using CPtr = const cpp::byte *; // Pointer to const raw data.
112	
113	// This type makes sure that we don't accidentally promote an integral type to
114	// another one. It is only constructible from the exact T type.
115	template <typename T> struct StrictIntegralType {
116	  static_assert(cpp::is_integral_v<T>);
117	
118	  // Can only be constructed from a T.
119	  template <typename U, cpp::enable_if_t<cpp::is_same_v<U, T>, bool> = 0>
120	  LIBC_INLINE StrictIntegralType(U value) : value(value) {}
121	
122	  // Allows using the type in an if statement.
123	  LIBC_INLINE explicit operator bool() const { return value; }
124	
125	  // If type is unsigned (bcmp) we allow bitwise OR operations.
126	  LIBC_INLINE StrictIntegralType
127	  operator|(const StrictIntegralType &Rhs) const {
128	    static_assert(!cpp::is_signed_v<T>);
129	    return value | Rhs.value;
130	  }
131	
132	  // For interation with the C API we allow explicit conversion back to the
133	  // `int` type.
134	  LIBC_INLINE explicit operator int() const {
135	    // bit_cast makes sure that T and int have the same size.
136	    return cpp::bit_cast<int>(value);
137	  }
138	
139	  // Helper to get the zero value.
140	  LIBC_INLINE static constexpr StrictIntegralType zero() { return {T(0)}; }
141	  LIBC_INLINE static constexpr StrictIntegralType nonzero() { return {T(1)}; }
142	
143	private:
144	  T value;
145	};
146	
147	using MemcmpReturnType = StrictIntegralType<int32_t>;
148	using BcmpReturnType = StrictIntegralType<uint32_t>;
149	
150	// This implements the semantic of 'memcmp' returning a negative value when 'a'
151	// is less than 'b', '0' when 'a' equals 'b' and a positive number otherwise.
152	LIBC_INLINE MemcmpReturnType cmp_uint32_t(uint32_t a, uint32_t b) {
153	  // We perform the difference as an int64_t.
154	  const int64_t diff = static_cast<int64_t>(a) - static_cast<int64_t>(b);
155	  // For the int64_t to int32_t conversion we want the following properties:
156	  // - int32_t[31:31] == 1 iff diff < 0
157	  // - int32_t[31:0] == 0 iff diff == 0
158	
159	  // We also observe that:
160	  // - When diff < 0: diff[63:32] == 0xffffffff and diff[31:0] != 0
161	  // - When diff > 0: diff[63:32] == 0 and diff[31:0] != 0
162	  // - When diff == 0: diff[63:32] == 0 and diff[31:0] == 0
163	  // - https://godbolt.org/z/8W7qWP6e5
164	  // - This implies that we can only look at diff[32:32] for determining the
165	  // sign bit for the returned int32_t.
166	
167	  // So, we do the following:
168	  // - int32_t[31:31] = diff[32:32]
169	  // - int32_t[30:0] = diff[31:0] == 0 ? 0 : non-0.
170	
171	  // And, we can achieve the above by the expression below. We could have also
172	  // used (diff64 >> 1) | (diff64 & 0x1) but (diff64 & 0xFFFF) is faster than
173	  // (diff64 & 0x1). https://godbolt.org/z/j3b569rW1
174	  return static_cast<int32_t>((diff >> 1) | (diff & 0xFFFF));
175	}
176	
177	// Returns a negative value if 'a' is less than 'b' and a positive value
178	// otherwise. This implements the semantic of 'memcmp' when we know that 'a' and
179	// 'b' differ.
180	LIBC_INLINE MemcmpReturnType cmp_neq_uint64_t(uint64_t a, uint64_t b) {
181	#if defined(LIBC_TARGET_ARCH_IS_X86)
182	  // On x86, the best strategy would be to use 'INT32_MAX' and 'INT32_MIN' for
183	  // positive and negative value respectively as they are one value apart:
184	  //   xor     eax, eax         <- free
185	  //   cmp     rdi, rsi         <- serializing
186	  //   adc     eax, 2147483647  <- serializing
187	
188	  // Unfortunately we found instances of client code that negate the result of
189	  // 'memcmp' to reverse ordering. Because signed integers are not symmetric
190	  // (e.g., int8_t ∈ [-128, 127]) returning 'INT_MIN' would break such code as
191	  // `-INT_MIN` is not representable as an int32_t.
192	
193	  // As a consequence, we use 5 and -5 which is still OK nice in terms of
194	  // latency.
195	  //   cmp     rdi, rsi         <- serializing
196	  //   mov     ecx, -5          <- can be done in parallel
197	  //   mov     eax, 5           <- can be done in parallel
198	  //   cmovb   eax, ecx         <- serializing
199	  static constexpr int32_t POSITIVE = 5;
200	  static constexpr int32_t NEGATIVE = -5;
201	#else
202	  // On RISC-V we simply use '1' and '-1' as it leads to branchless code.
203	  // On ARMv8, both strategies lead to the same performance.
204	  static constexpr int32_t POSITIVE = 1;
205	  static constexpr int32_t NEGATIVE = -1;
206	#endif
207	  static_assert(POSITIVE > 0);
208	  static_assert(NEGATIVE < 0);
209	  return a < b ? NEGATIVE : POSITIVE;
210	}
211	
212	// Loads bytes from memory (possibly unaligned) and materializes them as
213	// type.
214	template <typename T> LIBC_INLINE T load_unaligned(CPtr ptr) {
215	  T out;
216	  memcpy_inline<sizeof(T)>(&out, ptr);
217	  return out;
218	}
219	
220	// Stores a value of type T in memory (possibly unaligned).
221	template <typename T> LIBC_INLINE void store_unaligned(Ptr ptr, T value) {
222	  memcpy_inline<sizeof(T)>(ptr, &value);
223	}
224	
225	// On architectures that do not allow for unaligned access we perform several
226	// aligned accesses and recombine them through shifts and logicals operations.
227	// For instance, if we know that the pointer is 2-byte aligned we can decompose
228	// a 64-bit operation into four 16-bit operations.
229	
230	// Loads a 'ValueType' by decomposing it into several loads that are assumed to
231	// be aligned.
232	// e.g. load_aligned<uint32_t, uint16_t, uint16_t>(ptr);
233	template <typename ValueType, typename T, typename... TS>
234	LIBC_INLINE ValueType load_aligned(CPtr src) {
235	  static_assert(sizeof(ValueType) >= (sizeof(T) + ... + sizeof(TS)));
236	  static_assert(Endian::IS_LITTLE || Endian::IS_BIG, "Invalid endianness");
237	  const ValueType value = load_unaligned<T>(assume_aligned<sizeof(T)>(src));
238	
239	  if constexpr (sizeof...(TS) > 0) {
240	    const ValueType next = load_aligned<ValueType, TS...>(src + sizeof(T));
241	
242	    // Calculate shifts at compile time.
243	    // In Little Endian, 'value' stays at the bottom (shift 0).
244	    // In Big Endian, 'next' stays at the bottom (shift 0).
245	    constexpr size_t VAL_SHIFT = Endian::IS_LITTLE ? 0 : (sizeof(TS) + ...) * 8;
246	    constexpr size_t NEXT_SHIFT = Endian::IS_LITTLE ? sizeof(T) * 8 : 0;
247	
248	    // The compiler will constant-fold '<< 0' into a no-op.
249	    return (value << VAL_SHIFT) | (next << NEXT_SHIFT);
250	  } else {
251	    return value;
252	  }
253	}
254	
255	// Alias for loading a 'uint32_t'.
256	template <typename T, typename... TS>
257	LIBC_INLINE auto load32_aligned(CPtr src, size_t offset) {
258	  static_assert((sizeof(T) + ... + sizeof(TS)) == sizeof(uint32_t));
259	  return load_aligned<uint32_t, T, TS...>(src + offset);
260	}
261	
262	// Alias for loading a 'uint64_t'.
263	template <typename T, typename... TS>
264	LIBC_INLINE auto load64_aligned(CPtr src, size_t offset) {
265	  static_assert((sizeof(T) + ... + sizeof(TS)) == sizeof(uint64_t));
266	  return load_aligned<uint64_t, T, TS...>(src + offset);
267	}
268	
269	// Stores a 'ValueType' by decomposing it into several stores that are assumed
270	// to be aligned.
271	// e.g. store_aligned<uint32_t, uint16_t, uint16_t>(value, ptr);
272	template <typename ValueType, typename T, typename... TS>
273	LIBC_INLINE void store_aligned(ValueType value, Ptr dst) {
274	  static_assert(sizeof(ValueType) >= (sizeof(T) + ... + sizeof(TS)));
275	  constexpr size_t SHIFT = sizeof(T) * 8;
276	  if constexpr (Endian::IS_LITTLE) {
277	    store_unaligned<T>(assume_aligned<sizeof(T)>(dst), T(value & T(~0)));
278	    if constexpr (sizeof...(TS) > 0)
279	      store_aligned<ValueType, TS...>(value >> SHIFT, dst + sizeof(T));
280	  } else if constexpr (Endian::IS_BIG) {
281	    constexpr size_t OFFSET = (0 + ... + sizeof(TS));
282	    store_unaligned<T>(assume_aligned<sizeof(T)>(dst + OFFSET), value & ~T(0));
283	    if constexpr (sizeof...(TS) > 0)
284	      store_aligned<ValueType, TS...>(value >> SHIFT, dst);
285	  } else {
286	    static_assert(cpp::always_false<T>, "Invalid endianness");
287	  }
288	}
289	
290	// Alias for storing a 'uint32_t'.
291	template <typename T, typename... TS>
292	LIBC_INLINE void store32_aligned(uint32_t value, Ptr dst, size_t offset) {
293	  static_assert((sizeof(T) + ... + sizeof(TS)) == sizeof(uint32_t));
294	  store_aligned<uint32_t, T, TS...>(value, dst + offset);
295	}
296	
297	// Alias for storing a 'uint64_t'.
298	template <typename T, typename... TS>
299	LIBC_INLINE void store64_aligned(uint64_t value, Ptr dst, size_t offset) {
300	  static_assert((sizeof(T) + ... + sizeof(TS)) == sizeof(uint64_t));
301	  store_aligned<uint64_t, T, TS...>(value, dst + offset);
302	}
303	
304	// Advances the pointers p1 and p2 by offset bytes and decrease count by the
305	// same amount.
306	template <typename T1, typename T2>
307	LIBC_INLINE void adjust(ptrdiff_t offset, T1 *__restrict &p1,
308	                        T2 *__restrict &p2, size_t &count) {
309	  p1 += offset;
310	  p2 += offset;
311	  count -= static_cast<size_t>(offset);
312	}
313	
314	// Advances p1 and p2 so p1 gets aligned to the next SIZE bytes boundary
315	// and decrease count by the same amount.
316	// We make sure the compiler knows about the adjusted pointer alignment.
317	template <size_t SIZE, typename T1, typename T2>
318	void align_p1_to_next_boundary(T1 *__restrict &p1, T2 *__restrict &p2,
319	                               size_t &count) {
320	  adjust(static_cast<ptrdiff_t>(distance_to_next_aligned<SIZE>(p1)), p1, p2,
321	         count);
322	  p1 = assume_aligned<SIZE>(p1);
323	}
324	
325	// Same as align_p1_to_next_boundary above but with a single pointer instead.
326	template <size_t SIZE, typename T>
327	LIBC_INLINE void align_to_next_boundary(T *&p1, size_t &count) {
328	  const T *dummy = p1;
329	  align_p1_to_next_boundary<SIZE>(p1, dummy, count);
330	}
331	
332	// An enum class that discriminates between the first and second pointer.
333	enum class Arg { P1, P2, Dst = P1, Src = P2 };
334	
335	// Same as align_p1_to_next_boundary but allows for aligning p2 instead of p1.
336	// Precondition: &p1 != &p2
337	template <size_t SIZE, Arg AlignOn, typename T1, typename T2>
338	LIBC_INLINE void align_to_next_boundary(T1 *__restrict &p1, T2 *__restrict &p2,
339	                                        size_t &count) {
340	  if constexpr (AlignOn == Arg::P1)
341	    align_p1_to_next_boundary<SIZE>(p1, p2, count);
342	  else if constexpr (AlignOn == Arg::P2)
343	    align_p1_to_next_boundary<SIZE>(p2, p1, count); // swapping p1 and p2.
344	  else
345	    static_assert(cpp::always_false<T1>,
346	                  "AlignOn must be either Arg::P1 or Arg::P2");
347	}
348	
349	template <size_t SIZE> struct AlignHelper {
350	  LIBC_INLINE AlignHelper(CPtr ptr)
351	      : offset(distance_to_next_aligned<SIZE>(ptr)) {}
352	
353	  LIBC_INLINE bool not_aligned() const { return offset != SIZE; }
354	  uintptr_t offset;
355	};
356	
357	LIBC_INLINE void prefetch_for_write(CPtr dst) {
358	  __builtin_prefetch(dst, /*write*/ 1, /*max locality*/ 3);
359	}
360	
361	LIBC_INLINE void prefetch_to_local_cache(CPtr dst) {
362	  __builtin_prefetch(dst, /*read*/ 0, /*max locality*/ 3);
363	}
364	
365	} // namespace LIBC_NAMESPACE_DECL
366	
367	#endif // LLVM_LIBC_SRC_STRING_MEMORY_UTILS_UTILS_H
