101	inline_memcpy_x86_sse2_ge64_sw_prefetching(Ptr __restrict dst,
102	                                           CPtr __restrict src, size_t count) {
103	  using namespace LIBC_NAMESPACE::x86;
104	  inline_memcpy_prefetch(dst, src, K_ONE_CACHELINE);
105	  if (count <= 128)
106	    return builtin::Memcpy<64>::head_tail(dst, src, count);
107	  inline_memcpy_prefetch(dst, src, K_TWO_CACHELINES);
108	  // Aligning 'dst' on a 32B boundary.
109	  builtin::Memcpy<32>::block(dst, src);
110	  align_to_next_boundary<32, Arg::Dst>(dst, src, count);
111	  builtin::Memcpy<96>::block(dst, src);
112	  size_t offset = 96;
113	  // At this point:
114	  // - we copied between 96B and 128B,
115	  // - we prefetched cachelines at 'src + 64' and 'src + 128',
116	  // - 'dst' is 32B aligned,
117	  // - count >= 128.
118	  if (count < 352) {
119	    // Two cache lines at a time.
120	    while (offset + K_TWO_CACHELINES + 32 <= count) {
121	      inline_memcpy_prefetch(dst, src, offset + K_ONE_CACHELINE);
122	      inline_memcpy_prefetch(dst, src, offset + K_TWO_CACHELINES);
123	      // Copy one cache line at a time to prevent the use of `rep;movsb`.
124	      for (size_t i = 0; i < 2; ++i, offset += K_ONE_CACHELINE)
125	        builtin::Memcpy<K_ONE_CACHELINE>::block_offset(dst, src, offset);
126	    }
127	  } else {
128	    // Three cache lines at a time.
129	    while (offset + K_THREE_CACHELINES + 32 <= count) {
130	      inline_memcpy_prefetch(dst, src, offset + K_ONE_CACHELINE);
131	      inline_memcpy_prefetch(dst, src, offset + K_TWO_CACHELINES);
132	      inline_memcpy_prefetch(dst, src, offset + K_THREE_CACHELINES);
133	      // Copy one cache line at a time to prevent the use of `rep;movsb`.
134	      for (size_t i = 0; i < 3; ++i, offset += K_ONE_CACHELINE)
135	        builtin::Memcpy<K_ONE_CACHELINE>::block_offset(dst, src, offset);
136	    }
137	  }
138	  // We don't use 'loop_and_tail_offset' because it assumes at least one
139	  // iteration of the loop.
140	  while (offset + 32 <= count) {
141	    builtin::Memcpy<32>::block_offset(dst, src, offset);
142	    offset += 32;
143	  }
144	  return builtin::Memcpy<32>::tail(dst, src, count);
145	}
