152	  if (count <= 128)
153	    return builtin::Memcpy<64>::head_tail(dst, src, count);
154	  inline_memcpy_prefetch(dst, src, K_TWO_CACHELINES);
155	  inline_memcpy_prefetch(dst, src, K_THREE_CACHELINES);
156	  if (count < 256)
