158	  // Aligning 'dst' on a 32B boundary.
159	  builtin::Memcpy<32>::block(dst, src);
160	  align_to_next_boundary<32, Arg::Dst>(dst, src, count);
161	  builtin::Memcpy<224>::block(dst, src);
162	  size_t offset = 224;
163	  // At this point:
164	  // - we copied between 224B and 256B,
165	  // - we prefetched cachelines at 'src + 64', 'src + 128', and 'src + 196'
