171	    if (count >= x86::K_NTA_THRESHOLD) {
172	      while (offset + K_THREE_CACHELINES + 64 <= count) {
173	        for (size_t i = 0; i < 3; ++i, offset += K_ONE_CACHELINE) {
174	          generic::stream(dst + offset,
175	                          generic::load<x86::m256i>(src + offset));
