177	                          generic::load<x86::m256i>(src + offset + 32));
178	        }
179	      }
180	      generic::fence<x86::m256i>();
181	      need_prefetch_run = false;
182	    }
183	  }
184	  if (need_prefetch_run) {
185	    while (offset + K_THREE_CACHELINES + 64 <= count) {
186	      // Three cache lines at a time.
187	      inline_memcpy_prefetch(dst, src, offset + K_ONE_CACHELINE);
188	      inline_memcpy_prefetch(dst, src, offset + K_TWO_CACHELINES);
189	      inline_memcpy_prefetch(dst, src, offset + K_THREE_CACHELINES);
190	      // Copy one cache line at a time to prevent the use of `rep;movsb`.
191	      for (size_t i = 0; i < 3; ++i, offset += K_ONE_CACHELINE)
192	        builtin::Memcpy<K_ONE_CACHELINE>::block_offset(dst, src, offset);
193	    }
194	  }
195	  // We don't use 'loop_and_tail_offset' because it assumes at least one
196	  // iteration of the loop.
197	  while (offset + 64 <= count) {
198	    builtin::Memcpy<64>::block_offset(dst, src, offset);
199	    offset += 64;
200	  }
201	  return builtin::Memcpy<64>::tail(dst, src, count);
202	}
203	
204	[[maybe_unused]] LIBC_INLINE void
205	inline_memcpy_x86(Ptr __restrict dst, CPtr __restrict src, size_t count) {
206	  constexpr size_t VECTOR_SIZE = x86::K_AVX512_F ? 64
207	                                 : x86::K_AVX    ? 32
208	                                 : x86::K_SSE2   ? 16
209	                                                 : 8;
210	  if (count == 0)
211	    return;
212	  if (count == 1)
213	    return builtin::Memcpy<1>::block(dst, src);
214	  if (count == 2)
215	    return builtin::Memcpy<2>::block(dst, src);
216	  if (count == 3)
217	    return builtin::Memcpy<3>::block(dst, src);
218	  if (count == 4)
219	    return builtin::Memcpy<4>::block(dst, src);
220	  if (count < 8)
221	    return builtin::Memcpy<4>::head_tail(dst, src, count);
222	  // If count is equal to a power of 2, we can handle it as head-tail
223	  // of both smaller size and larger size (head-tail are either
224	  // non-overlapping for smaller size, or completely collapsed
225	  // for larger size). It seems to be more profitable to do the copy
226	  // with the larger size, if it's natively supported (e.g. doing
227	  // 2 collapsed 32-byte moves for count=64 if AVX2 is supported).
228	  // But it's not profitable to use larger size if it's not natively
229	  // supported: we will both use more instructions and handle fewer
230	  // sizes in earlier branches.
231	  if (VECTOR_SIZE >= 16 ? count < 16 : count <= 16)
232	    return builtin::Memcpy<8>::head_tail(dst, src, count);
233	  if (VECTOR_SIZE >= 32 ? count < 32 : count <= 32)
234	    return builtin::Memcpy<16>::head_tail(dst, src, count);
235	  if (VECTOR_SIZE >= 64 ? count < 64 : count <= 64)
236	    return builtin::Memcpy<32>::head_tail(dst, src, count);
237	  if constexpr (x86::K_AVX) {
238	    if constexpr (x86::K_USE_SOFTWARE_PREFETCHING) {
239	      return inline_memcpy_x86_avx_ge64_sw_prefetching(dst, src, count);
240	    } else {
241	      return inline_memcpy_x86_avx_ge64(dst, src, count);
242	    }
243	  } else {
244	    if constexpr (x86::K_USE_SOFTWARE_PREFETCHING) {
245	      return inline_memcpy_x86_sse2_ge64_sw_prefetching(dst, src, count);
246	    } else {
247	      return inline_memcpy_x86_sse2_ge64(dst, src, count);
248	    }
249	  }
250	}
251	
252	[[maybe_unused]] LIBC_INLINE void
253	inline_memcpy_x86_maybe_interpose_repmovsb(Ptr __restrict dst,
254	                                           CPtr __restrict src, size_t count) {
255	  if constexpr (x86::K_REP_MOVSB_THRESHOLD == 0) {
256	    return x86::Memcpy::repmovsb(dst, src, count);
257	  } else if constexpr (x86::K_REP_MOVSB_THRESHOLD == SIZE_MAX) {
258	    return inline_memcpy_x86(dst, src, count);
259	  } else {
260	    if (LIBC_UNLIKELY(count >= x86::K_REP_MOVSB_THRESHOLD))
261	      return x86::Memcpy::repmovsb(dst, src, count);
262	    else
263	      return inline_memcpy_x86(dst, src, count);
264	  }
265	}
