62	// Memcpy repmovsb implementation
63	struct Memcpy {
64	  LIBC_INLINE static void repmovsb(void *dst, const void *src, size_t count) {
65	#ifdef LIBC_COMPILER_IS_MSVC
66	    __movsb(static_cast<unsigned char *>(dst),
67	            static_cast<const unsigned char *>(src), count);
68	#else
69	    asm volatile("rep movsb" : "+D"(dst), "+S"(src), "+c"(count) : : "memory");
70	#endif // LIBC_COMPILER_IS_MSVC
71	  }
