80	template <typename T> LIBC_INLINE void stream(Ptr dst, T value) {
81	#if __has_builtin(__builtin_nontemporal_store)
82	  __builtin_nontemporal_store(value, reinterpret_cast<T *>(dst));
83	#else
84	  // Falling back to regular stores is always safe
85	  store<T>(dst, value);
86	#endif
