89	template <typename T> LIBC_INLINE void fence() {
90	  // This won't be reached when nothing fancy is enabled, but it can be
91	  // referenced in if constexpr context, so it's still defined, as a no-op.
92	#if LIBC_TARGET_HAS_X86_INTRIN
93	  _mm_sfence();
94	#endif
