108	LIBC_INLINE MemcmpReturnType cmp<uint16_t>(CPtr p1, CPtr p2, size_t offset) {
109	  return static_cast<int32_t>(load_be<uint16_t>(p1, offset)) -
110	         static_cast<int32_t>(load_be<uint16_t>(p2, offset));
111	}
